ALTER TABLE offline_package_installation
    ALTER COLUMN last_reported_by_account_id TYPE UUID
    USING CASE last_reported_by_account_id
        WHEN '11111111-1111-1111-1111-111111110001' THEN '11111111-1111-1111-1111-111111110001'::uuid
        WHEN '11111111-1111-1111-1111-111111110002' THEN '11111111-1111-1111-1111-111111110002'::uuid
        WHEN '11111111-1111-1111-1111-111111110003' THEN '11111111-1111-1111-1111-111111110003'::uuid
        WHEN '11111111-1111-1111-1111-111111110004' THEN '11111111-1111-1111-1111-111111110004'::uuid
        WHEN '11111111-1111-1111-1111-111111110005' THEN '11111111-1111-1111-1111-111111110005'::uuid
        WHEN '11111111-1111-1111-1111-111111110006' THEN '11111111-1111-1111-1111-111111110006'::uuid
        WHEN '11111111-1111-1111-1111-111111110007' THEN '11111111-1111-1111-1111-111111110007'::uuid
        WHEN '11111111-1111-1111-1111-111111110008' THEN '11111111-1111-1111-1111-111111110008'::uuid
        WHEN '11111111-1111-1111-1111-111111119903' THEN '11111111-1111-1111-1111-111111119903'::uuid
        ELSE last_reported_by_account_id::uuid
    END;
